namespace Icon256Ui {
struct Appearance {
  uint8_t look = 0; // solid, gradient, classic rain
  uint8_t gradient = 0;
  uint8_t direction = 0;
  uint32_t color = 0xFFFFFF;
};
static Appearance appearances[4] = {{}, {}, {1, 4, 1, 0x40E866}, {2, 3, 1, 0x40E866}};
static bool active = false;
static bool hideSeconds = false;
static bool appearanceDirty = false;
static uint32_t appearanceChanged = 0;
static const uint8_t effects[] = {250, FX_MODE_2DSCROLLTEXT, FX_MODE_2DGEQ, FX_MODE_2DMATRIX};
static const char* const modeNames[] = {"clock", "text", "eq", "rain"};

static int modeIndex() {
  for (unsigned i = 0; i < 4; i++) if (strip.getMainSegment().mode == effects[i]) return i;
  return -1;
}

static void writeAppearance(JsonObject obj, const Appearance& a) {
  obj["look"] = a.look;
  obj["gradient"] = a.gradient;
  obj["direction"] = a.direction;
  obj["color"] = a.color;
}

static void readAppearance(JsonObject obj, Appearance& a) {
  if (obj["look"].is<int>()) a.look = constrain(obj["look"].as<int>(), 0, 2);
  if (obj["gradient"].is<int>()) a.gradient = constrain(obj["gradient"].as<int>(), 0, 4);
  if (obj["direction"].is<int>()) a.direction = constrain(obj["direction"].as<int>(), 0, 2);
  if (obj["color"].is<uint32_t>()) a.color = obj["color"].as<uint32_t>() & 0xFFFFFF;
}

static void writeState(JsonObject obj) {
  obj["active"] = active;
  for (unsigned i = 0; i < 4; i++) writeAppearance(obj.createNestedObject(modeNames[i]), appearances[i]);
}

static void readState(JsonObject obj) {
  if (obj["active"].is<bool>()) active = obj["active"];
  for (unsigned i = 0; i < 4; i++) readAppearance(obj[modeNames[i]], appearances[i]);
}

static uint32_t tint(const Appearance& a, unsigned x, unsigned y) {
  if (a.look == 0) return a.color;
  if (a.look == 2) return 0x40E866;
  static const uint32_t stops[5][6] = {
    {0xFFBC77, 0xEF6CA7, 0x9673ED},
    {0x70E4BD, 0x5DBEEC, 0x7671EF},
    {0x82E5AC, 0x8EA2FF, 0xE984D4},
    {0xFF4040, 0xFFDB38, 0x40E866, 0x38C9FF, 0x725CFF, 0xEF54CD},
    {0xFF4545, 0xFFDB38, 0x40E866}
  };
  unsigned coordinate = a.direction == 1 ? y : a.direction == 2 ? x+y : x;
  unsigned denominator = a.direction == 2 ? 30 : 15;
  unsigned count = a.gradient == 3 ? 6 : 3;
  unsigned pos = coordinate * (count-1) * 255 / denominator;
  unsigned index = min(pos / 255, count-2);
  return color_blend(stops[a.gradient][index], stops[a.gradient][index+1], pos-index*255);
}

// Tint the composed frame, not the effect's working buffer (rain trails use that buffer).
static void draw() {
  int mode = modeIndex();
  if (!active || mode < 0 || !strip.isMatrix || Segment::maxWidth != 16 || Segment::maxHeight != 16) return;
  const Appearance& a = appearances[mode];
  for (unsigned y=0; y<16; y++) for (unsigned x=0; x<16; x++) {
    uint32_t c = strip.getPixelColorXY(x,y);
    uint8_t level = max(R(c), max(G(c), B(c)));
    // Rain uses explicit white spawn pixels; retain white leading letters.
    uint32_t target = mode == 3 && R(c) == G(c) && G(c) == B(c) ? 0xFFFFFF : tint(a,x,y);
    strip.setPixelColor(y*16+x, color_blend(BLACK, target, level));
  }
}

static void serve(AsyncWebServerRequest* request) {
  AsyncWebServerResponse* response = request->beginResponse_P(200, "text/html", ICON256_PAGE, sizeof(ICON256_PAGE));
  response->addHeader("Content-Encoding", "gzip");
  response->addHeader("Cache-Control", "no-cache");
  request->send(response);
}

static void setup() {
  server.on("/icon256", HTTP_GET, serve);
  // Registered before initServer(). Let upstream handle explicit advanced URLs.
  server.on("/", HTTP_GET, serve).setFilter([](AsyncWebServerRequest* request) {
    return !request->hasArg("advanced") && !request->hasArg("sliders");
  });
}
}
